// Valida la entrada del subworkflow. Los captions vienen de un modelo: se revisa la forma antes de aplicar reglas
const THEMES = ["Libros", "Vinilos", "Teatro", "Fiestas", "Conciertos", "Conversatorios", "Proyecciones", "Presentaciones", "Café", "Comida", "Licores"];
const input = $input.first().json;
const contentItemId = String(input.content_item_id ?? '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(contentItemId)) {
  throw new Error('validation: content_item_id no es un UUID');
}
const theme = String(input.theme ?? '').trim();
if (!THEMES.includes(theme)) throw new Error('validation: theme no es un tema de Le Tiende');

const c = input.captions;
if (!c || typeof c !== 'object' || Array.isArray(c)) throw new Error('validation: captions debe ser un objeto');
const isStrArr = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
const okShape = ['caption_instagram', 'caption_tiktok', 'title_youtube', 'caption_youtube', 'suggested_time_note'].every((k) => typeof c[k] === 'string')
  && ['hashtags_instagram', 'hashtags_tiktok', 'tags_youtube'].every((k) => isStrArr(c[k]));
if (!okShape) throw new Error('validation: captions no cumple el esquema de WF11');
if (JSON.stringify(c).length > 30000) throw new Error('validation: captions demasiado largo');

// Se reconstruye con las claves conocidas
const captions = {};
for (const k of ['caption_instagram', 'hashtags_instagram', 'caption_tiktok', 'hashtags_tiktok', 'title_youtube', 'caption_youtube', 'tags_youtube', 'suggested_time_note']) captions[k] = c[k];
return [{ json: { content_item_id: contentItemId, captions, theme, started_at: new Date().toISOString() } }];

// Abre la fila del paso en pipeline_steps ('started'); el intento es el último + 1
const { content_item_id, captions, theme, started_at } = $input.first().json;
const base = `${$env.SUPABASE_URL}/rest/v1/pipeline_steps`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' };

const previous = await this.helpers.httpRequest({
  method: 'GET', url: base, headers, json: true,
  qs: { content_item_id: `eq.${content_item_id}`, step: 'eq.validate_captions', select: 'attempt', order: 'attempt.desc', limit: 1 },
});
const attempt = (previous?.[0]?.attempt ?? 0) + 1;

const created = await this.helpers.httpRequest({
  method: 'POST', url: base, json: true,
  headers: { ...headers, Prefer: 'return=representation' },
  body: { content_item_id, step: 'validate_captions', attempt, status: 'started', started_at, n8n_execution_id: String($execution.id) },
});
const row = Array.isArray(created) ? created[0] : created;
if (!row?.id) throw new Error('supabase: pipeline_steps no devolvió el id de la fila');

return [{ json: { content_item_id, captions, theme, started_at, step_id: row.id, attempt } }];

// Aplica los validadores deterministas
// Listas de hashtags leídas del prompt de WF02 (nodo «Preparar prompt Gemini»)
const GENERIC = ["LeTiende", "CulturaBogota", "CafeCultural", "PuntoDeEncuentro", "AgendaCultural", "BarCultural", "BogotaCultura", "DondeIrEnBogota"];
const THEMED = {"Libros": ["Lectura", "LibrosColombia", "Bookstagram", "NovedadEditorial", "RecomendacionDeLectura"], "Vinilos": ["Vinilos", "MusicaEnVinilo", "VinilosColombia", "Tocadiscos", "VinylCollector"], "Teatro": ["TeatroBogota", "ObraDeTeatro", "DireccionTeatral", "EscenaColombiana"], "Conciertos": ["ConciertosBogota", "MusicaEnVivo", "LiveMusic", "ShowEnBogota"], "Café": ["CafeDeEspecialidad", "CafeColombiano", "Barista", "CoffeeLover"], "Comida": ["GastronomiaBogota", "MenuDelDia", "FoodieBogota"], "Licores": ["Cocktails", "BarBogota", "Mixologia", "Drinks"], "Fiestas": ["FiestaBogota", "NocheBogota", "RumbaBogota"], "Proyecciones": ["CineBogota", "Proyeccion", "CineIndependiente"], "Conversatorios": ["Conversatorio", "CharlaCultural", "Debate"], "Presentaciones": ["PresentacionDeLibro", "Lanzamiento", "EventoCultural"]};

const { content_item_id, captions, theme, step_id } = $input.first().json;
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const tag = (h) => String(h).replace(/^#/, '').trim();
const c = JSON.parse(JSON.stringify(captions));
const fixes = [];
const violations = [];

// --- Arreglos mecánicos
// 1. «Le Tiende» siempre en negrita en el caption de Instagram
if (/Le Tiende/.test(c.caption_instagram)) {
  const fixed = c.caption_instagram.replace(/(?<!\*)Le Tiende(?!\*)/g, '**Le Tiende**');
  if (fixed !== c.caption_instagram) { c.caption_instagram = fixed; fixes.push({ rule: 'marca', detail: 'Le Tiende puesto en negrita' }); }
} else {
  // Sin mención: se agrega un cierre fijo en vez de pedir otra llamada a la API
  c.caption_instagram = `${c.caption_instagram.trimEnd()}\n\nTe esperamos en **Le Tiende**.`;
  fixes.push({ rule: 'marca', detail: 'caption sin mención: agregado el cierre «Te esperamos en **Le Tiende**.»' });
}

// 2. Hashtags: solo los genéricos y los del tema; se completan hasta el mínimo y se recortan al máximo
const allowed = [...(THEMED[theme] ?? []), ...GENERIC];
const allowedSet = new Set(allowed.map(norm));
const fixTags = (key, min, max) => {
  const seen = new Set();
  const kept = [];
  const dropped = [];
  for (const raw of c[key]) {
    const h = tag(raw);
    if (!allowedSet.has(norm(h)) || seen.has(norm(h))) { dropped.push(h); continue; }
    seen.add(norm(h));
    kept.push(h);
  }
  const added = [];
  for (const h of allowed) {
    if (kept.length >= min) break;
    if (!seen.has(norm(h))) { seen.add(norm(h)); kept.push(h); added.push(h); }
  }
  const cut = kept.splice(max);
  c[key] = kept;
  if (dropped.length) fixes.push({ rule: 'hashtags_tema', detail: `${key}: descartados fuera de lista (${dropped.join(', ')})` });
  if (added.length) fixes.push({ rule: 'limites', detail: `${key}: completados hasta ${min} (${added.join(', ')})` });
  if (cut.length) fixes.push({ rule: 'limites', detail: `${key}: recortados a ${max} (${cut.join(', ')})` });
};
fixTags('hashtags_instagram', 10, 15);
fixTags('hashtags_tiktok', 5, 7);

// 3. tags de YouTube: sin lugares prohibidos y hasta 15
const tagsOk = c.tags_youtube.filter((t) => !/teusaquillo|chapinero/i.test(t));
if (tagsOk.length !== c.tags_youtube.length) fixes.push({ rule: 'geografia', detail: 'tags_youtube: descartados Teusaquillo/Chapinero' });
c.tags_youtube = tagsOk.slice(0, 15);
if (tagsOk.length > 15) fixes.push({ rule: 'limites', detail: 'tags_youtube: recortados a 15' });

// --- Reglas que piden reintento (no se arreglan sin cambiar el sentido del texto)
const fields = ['caption_instagram', 'caption_tiktok', 'title_youtube', 'caption_youtube'];
const VOSEO = /(?<!\p{L})(vos|tenés|querés|sabés|podés|vení|mirá|descubrí|encontrá|disfrutá|visitá|conocé|pedí|probá|acompañá|llevate|sumate|animate)(?!\p{L})/iu;
const GENERICAS = /no te lo pierdas|haz clic aquí/i;
const EMOJI = /\p{Extended_Pictographic}/gu;
const LIMITS = { caption_instagram: 2000, caption_tiktok: 150, title_youtube: 80 };
for (const [k, max] of Object.entries(LIMITS)) {
  if (c[k].length > max) violations.push({ rule: 'limites', field: k, detail: `${k} tiene ${c[k].length} caracteres y el máximo es ${max}` });
}
for (const k of fields) {
  const t = c[k];
  if (VOSEO.test(t)) violations.push({ rule: 'tuteo', field: k, detail: `${k} usa voseo; escribe siempre con tuteo` });
  if ((t.match(EMOJI) ?? []).length > 3) violations.push({ rule: 'emojis', field: k, detail: `${k} tiene más de 3 emojis` });
  if (GENERICAS.test(t)) violations.push({ rule: 'frases_genericas', field: k, detail: `${k} usa una frase genérica prohibida` });
  if (/chapinero/i.test(t)) violations.push({ rule: 'geografia', field: k, detail: `${k} menciona Chapinero; Le Tiende está sobre el Parkway` });
  if (/teusaquillo/i.test(t)) violations.push({ rule: 'parkway', field: k, detail: `${k} menciona Teusaquillo; no se nombra` });
  if (/(?<!el |El |al |del )(?<![#\p{L}])parkway(?!\p{L})/iu.test(t)) violations.push({ rule: 'parkway', field: k, detail: `${k} escribe Parkway sin artículo («el Parkway»)` });
}

const valid = violations.length === 0;
// Texto para el reintento a WF11 (lo arma el orquestador); null si no hace falta
const retry_feedback = valid ? null : `Corrige estas fallas del borrador anterior, sin cambiar los datos del evento:\n${violations.map((v) => `- ${v.detail}`).join('\n')}`;

return [{ json: {
  content_item_id, step_id, captions: c, valid, violations, fixes, retry_feedback,
  step_patch: { status: 'succeeded', finished_at: new Date().toISOString(), cost_usd: 0 },
} }];

// Normaliza el fallo de cualquier nodo para pipeline_steps, error_log y Telegram
const raw = $input.first().json;
const message = String(raw.error?.message ?? raw.error ?? raw.message ?? 'Error sin mensaje')
  // Nunca registrar el token del bot que va en las URLs de archivos de Telegram
  .replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***')
  .slice(0, 2000);
const prefix = (message.match(/^([a-z_]+):/) ?? [])[1];
// Sin prefijo propio (p. ej. un 404 del nodo HTTP), la etapa es el último nodo que llegó a ejecutarse
const stages = [['Registrar inicio', 'supabase'], ['Aplicar reglas', 'rules'], ['Cerrar paso exitoso', 'supabase']];
const stage = stages.filter(([node]) => $(node).isExecuted).pop()?.[1];
const error_type = prefix ?? stage ?? 'execution_error';

// Desde una rama de error, first() sin argumentos lee la salida 1 (error) del nodo: hay que pedir la salida 0
const input = $('Entrada').first(0, 0)?.json ?? {};
// Si 'Registrar inicio' no corrió o falló, no hay fila abierta en pipeline_steps
const step = $('Registrar inicio').isExecuted ? ($('Registrar inicio').first(0, 0)?.json ?? null) : null;
const contentItemId = /^[0-9a-f-]{36}$/i.test(String(input.content_item_id ?? '')) ? String(input.content_item_id).toLowerCase() : null;
const status = error_type === 'waiting_quota' ? 'waiting_quota' : 'failed';

return [{ json: {
  has_step: Boolean(step?.step_id),
  step_id: step?.step_id ?? null,
  step_patch: { status, finished_at: new Date().toISOString(), error_type, error_message: message },
  error_log_row: {
    workflow: '12-validar-captions', content_item_id: contentItemId, error_type, error_message: message,
    stack_trace: JSON.stringify({ execution_id: $execution.id, error: raw.error ?? raw }).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').slice(0, 8000),
  },
  telegram_text: `⚠️ 12 - Validar captions (${error_type})\nItem: ${contentItemId ?? 'sin id válido'}\nEjecución: ${$execution.id}\n\n${message.slice(0, 500)}`,
  result: { ok: false, content_item_id: contentItemId, status, error_type, error_message: message },
} }];
